Cypher query: MATCH (a:Article)-[:PUBLISHED_BY]->(pub:Publisher)
WHERE (toLower(coalesce(pub.name, '')) CONTAINS 'techcrunch' OR any(alias IN coalesce(pub.aliases, []) WHERE toLower(alias) CONTAINS 'techcrunch'))
  AND (
    toLower(coalesce(a.name, '')) CONTAINS 'gemini'
    OR toLower(coalesce(a.name, '')) CONTAINS 'antitrust'
    OR toLower(coalesce(a.name, '')) CONTAINS 'lawsuit'
    OR EXISTS {
      MATCH (a)-[:MENTIONS|PART_OF]->(x:__Entity__)
      WHERE toLower(coalesce(x.name, '')) CONTAINS 'gemini ultra'
         OR toLower(coalesce(x.name, '')) CONTAINS 'antitrust'
         OR toLower(coalesce(x.name, '')) CONTAINS 'lawsuit'
         OR any(alias IN coalesce(x.aliases, []) WHERE toLower(alias) CONTAINS 'gemini ultra' OR toLower(alias) CONTAINS 'antitrust' OR toLower(alias) CONTAINS 'lawsuit')
    }
  )
OPTIONAL MATCH (a)-[:MENTIONS]->(e:__Entity__)
OPTIONAL MATCH (a)-[:MENTIONS]->(t:Topic)
OPTIONAL MATCH (g:Organization)-[:ACCUSED_OF]->(issue:Topic)
WHERE toLower(coalesce(g.name, '')) CONTAINS 'google'
  AND EXISTS { MATCH (a)-[:MENTIONS]->(issue) }
RETURN a.name AS article, a.published_on AS date,
       collect(DISTINCT e.name) AS people_and_entities,
       collect(DISTINCT CASE WHEN e:Person THEN e.name END) AS people,
       collect(DISTINCT t.name) AS reported_issues,
       collect(DISTINCT issue.name) AS issues_alleged_about_google
LIMIT 10
