       OR any(alias IN coalesce(p.aliases, []) WHERE toLower(alias) CONTAINS 'techcrunch'))
  AND EXISTS { MATCH (a)-[:MENTIONS]->(u) }
  AND (
    toLower(a.name) CONTAINS 'q3'
    OR toLower(a.name) CONTAINS 'financial'
